from src.admin import dashboard, audit_log
import base64
import json
import time


def _make_valid_token(exp_offset=3600):
    """Helper to create a valid token with proper exp claim."""
    payload = {"exp": time.time() + exp_offset}
    payload_json = json.dumps(payload)
    payload_b64 = base64.urlsafe_b64encode(payload_json.encode()).decode().rstrip("=")
    return f"header.{payload_b64}.signature"


def test_dashboard_returns_stats():
    result = dashboard(_make_valid_token())
    assert result == {
        "total_users": 1000,
        "total_orders": 5000,
        "revenue": 250000.00,
    }


def test_dashboard_rejects_empty_token():
    try:
        dashboard("")
        assert False, "Expected ValueError for empty token"
    except ValueError:
        pass


def test_dashboard_rejects_expired_token():
    token = _make_valid_token(exp_offset=-3600)
    try:
        dashboard(token)
        assert False, "Expected ValueError for expired token"
    except ValueError as e:
        assert "expired" in str(e).lower()


def test_dashboard_rejects_token_missing_exp():
    payload = {"sub": "admin"}
    payload_json = json.dumps(payload)
    payload_b64 = base64.urlsafe_b64encode(payload_json.encode()).decode().rstrip("=")
    token = f"header.{payload_b64}.signature"
    try:
        dashboard(token)
        assert False, "Expected ValueError for missing exp"
    except ValueError as e:
        assert "missing expiration" in str(e).lower()


def test_audit_log_returns_entry():
    result = audit_log(_make_valid_token(), "user.delete", "Removed user-42")
    assert result["action"] == "user.delete"
    assert result["details"] == "Removed user-42"
    assert result["timestamp"] == "2026-08-20T00:00:00Z"


def test_audit_log_rejects_empty_token():
    try:
        audit_log("", "login", "Admin signed in")
        assert False, "Expected ValueError for empty token"
    except ValueError:
        pass


def test_audit_log_rejects_expired_token():
    token = _make_valid_token(exp_offset=-3600)
    try:
        audit_log(token, "config.update", "Changed setting")
        assert False, "Expected ValueError for expired token"
    except ValueError as e:
        assert "expired" in str(e).lower()


def test_audit_log_preserves_empty_action_and_details():
    """audit_log does not validate action/details; they are echoed as given."""
    result = audit_log(_make_valid_token(), "", "")
    assert result["action"] == ""
    assert result["details"] == ""
```

Coverage summary: dashboard success returns exact stats dict; dashboard errors for empty token, expired token (message contains 'expired'), and token missing `exp` (message contains 'missing expiration'). audit_log success echoes action/details with fixed timestamp; audit_log errors for empty and expired tokens; edge case that empty action/details
